routes = {"/users": "users-svc", "/orders": "orders-svc", "/search": "search-svc"}
calls = {}

def gateway(path, token, limit=3):
    if token is None:
        return "401 no token"
    calls[token] = calls.get(token, 0) + 1
    if calls[token] > limit:
        return "429 too many calls"
    prefix = "/" + path.split("/")[1]
    return routes.get(prefix, "404 no such route")

for path, token in [("/orders/42", "t7"), ("/search/shoe", "t7"), ("/orders/42", None),
                    ("/users/7", "t7"), ("/orders/43", "t7"), ("/cart", "t9")]:
    print(f"{path:13}", gateway(path, token))
